#!/usr/bin/env python3
"""Apply Step 18 WNBA market-band validation to the existing master-test core.

Run from the repository root. This updater does not modify markets.yaml and does
not create a separate validation engine. It updates the existing
basketball_pipeline_final_master_test_core.py in place after validating that the
launcher already exposes dratings/sdv/ensemble model-source selection.
"""
from __future__ import annotations

from pathlib import Path

ROOT = Path("docs/win/basketball")
CORE = ROOT / "scripts/testing/basketball_pipeline_final_master_test_core.py"
LAUNCHER = ROOT / "scripts/testing/basketball_pipeline_final_master_test.py"

ADDITIONS = 'import hashlib\n\n# Step 18 additions for basketball_pipeline_final_master_test_core.py\n\nSDV_MODEL_CONFIG = Path(\n    \'docs/win/basketball/config/sdv_model.yaml\'\n)\nSDV_PREDICT_SCRIPT = Path(\n    \'docs/win/basketball/scripts/00_intake/sdv_predict.py\'\n)\nENSEMBLE_SCRIPT = Path(\n    \'docs/win/basketball/scripts/00_intake/basketball_model_ensemble.py\'\n)\nWNBA_MARKET_BANDS_REPORT = Path(\n    \'docs/win/basketball/backtest/model_validation/\'\n    \'sdv_ensemble/wnba/WNBA_MARKET_BANDS_REPORT.txt\'\n)\n\n\ndef _load_module_with_sibling_imports(name: str, path: Path):\n    parent = str(path.resolve().parent)\n    inserted = parent not in sys.path\n    if inserted:\n        sys.path.insert(0, parent)\n    try:\n        return load_module_from_path(name, path)\n    finally:\n        if inserted:\n            try:\n                sys.path.remove(parent)\n            except ValueError:\n                pass\n\n\ndef _normalize_match_text(value: Any) -> list[str]:\n    text = \'\' if value is None else str(value)\n    return \'\'.join(\n        ch.lower() if ch.isalnum() else \' \'\n        for ch in text\n    ).split()\n\n\ndef _normalized_team(value: Any) -> str:\n    return \' \'.join(_normalize_match_text(value))\n\n\ndef _normalized_date(value: Any) -> str:\n    text = \'\' if value is None else str(value).strip()\n    text = text[:10].replace(\'_\', \'-\').replace(\'/\', \'-\')\n    try:\n        return pd.Timestamp(text).strftime(\'%Y-%m-%d\')\n    except Exception:\n        return \'\'\n\n\ndef _target_team_candidates(row: dict[str, Any], side: str) -> set[str]:\n    values = {\n        _normalized_team(row.get(f\'{side}_team\')),\n        _normalized_team(row.get(f\'{side}_display_name\')),\n        _normalized_team(row.get(f\'{side}_short_display_name\')),\n        _normalized_team(row.get(f\'{side}_name\')),\n        _normalized_team(row.get(f\'{side}_location\')),\n    }\n    values.discard(\'\')\n    return values\n\n\ndef _historical_feature_map(\n    base_df: pd.DataFrame,\n    league: str,\n    internal_season: int,\n    sdv_module: Any,\n    sdv_cfg: dict[str, Any],\n) -> dict[str, dict[str, Any]]:\n    try:\n        import polars as pl\n    except Exception as exc:\n        raise SystemExit(\n            \'SDV/ensemble historical validation requires polars.\'\n        ) from exc\n\n    paths = sdv_module.feature_generation.configured_paths(sdv_cfg)\n    feature_path = (\n        paths[\'history_output_root\']\n        / league.lower()\n        / f\'{internal_season}_{league.upper()}_features.parquet\'\n    )\n    if not feature_path.exists():\n        raise FileNotFoundError(\n            f\'Missing historical SDV feature file: {feature_path}\'\n        )\n\n    feature_rows = pl.read_parquet(feature_path).to_dicts()\n    if not feature_rows:\n        raise RuntimeError(\n            f\'Historical SDV feature file has zero rows: {feature_path}\'\n        )\n\n    history_root = paths[\'history_input_root\']\n    target_rows = (\n        sdv_module.feature_generation.historical_target_rows(\n            history_root,\n            league.lower(),\n            internal_season,\n        )\n    )\n\n    feature_by_id: dict[str, dict[str, Any]] = {}\n    for row in feature_rows:\n        game_id = sdv_module.clean_id(row.get(\'game_id\'))\n        if not game_id:\n            raise RuntimeError(\n                f\'{feature_path}: feature row has blank game_id\'\n            )\n        if game_id in feature_by_id:\n            raise RuntimeError(\n                f\'{feature_path}: duplicate feature game_id={game_id}\'\n            )\n        feature_by_id[game_id] = row\n\n    target_by_id: dict[str, dict[str, Any]] = {}\n    for row in target_rows:\n        game_id = sdv_module.clean_id(\n            row.get(\'game_id\') or row.get(\'id\')\n        )\n        if game_id:\n            target_by_id[game_id] = row\n\n    base_ids = [str(v).strip() for v in base_df[\'game_id\'].tolist()]\n    if len(base_ids) != len(set(base_ids)):\n        dupes = sorted(\n            pd.Series(base_ids)[pd.Series(base_ids).duplicated()].unique().tolist()\n        )\n        raise RuntimeError(\n            f\'Historical input contains duplicate game_id values: {dupes}\'\n        )\n\n    match_by_base_id: dict[str, dict[str, Any]] = {}\n    unresolved: list[str] = []\n\n    # Primary match: exact canonical game_id.\n    for base_id in base_ids:\n        if base_id in feature_by_id:\n            match_by_base_id[base_id] = feature_by_id[base_id]\n\n    # Fallback for older combined files whose game_id is a synthetic string:\n    # match by date + exact normalized home/away display name from SDV games.\n    if len(match_by_base_id) != len(base_ids):\n        target_candidates: list[tuple[str, str, set[str], set[str]]] = []\n        for sdv_id, target in target_by_id.items():\n            if sdv_id not in feature_by_id:\n                continue\n            parsed_target_date = (\n                sdv_module.feature_generation.row_game_date(target)\n            )\n            target_date = (\n                parsed_target_date.strftime(\'%Y-%m-%d\')\n                if parsed_target_date is not None\n                else \'\'\n            )\n            homes = _target_team_candidates(target, \'home\')\n            aways = _target_team_candidates(target, \'away\')\n            if target_date and homes and aways:\n                target_candidates.append((sdv_id, target_date, homes, aways))\n\n        for _, base_row in base_df.iterrows():\n            base_id = str(base_row[\'game_id\']).strip()\n            if base_id in match_by_base_id:\n                continue\n            base_date = _normalized_date(base_row.get(\'game_date\'))\n            base_home = _normalized_team(base_row.get(\'home_team\'))\n            base_away = _normalized_team(base_row.get(\'away_team\'))\n            matches = [\n                sdv_id\n                for sdv_id, target_date, homes, aways in target_candidates\n                if (\n                    target_date == base_date\n                    and base_home in homes\n                    and base_away in aways\n                )\n            ]\n            if len(matches) == 1:\n                match_by_base_id[base_id] = feature_by_id[matches[0]]\n            else:\n                unresolved.append(\n                    f\'{base_id} ({base_date} | {base_row.get("home_team")} vs \'\n                    f\'{base_row.get("away_team")}) matches={matches}\'\n                )\n\n    if len(match_by_base_id) != len(base_ids):\n        missing = [\n            base_id for base_id in base_ids if base_id not in match_by_base_id\n        ]\n        raise RuntimeError(\n            \'Historical SDV feature coverage failed. Missing base game_id values=\'\n            f\'{missing}. Match detail={unresolved}\'\n        )\n\n    return match_by_base_id\n\n\ndef _historical_sdv_predictions(\n    base_df: pd.DataFrame,\n    league: str,\n    internal_season: int,\n) -> dict[str, dict[str, Any]]:\n    if not SDV_MODEL_CONFIG.exists():\n        raise FileNotFoundError(SDV_MODEL_CONFIG)\n\n    sdv_module = _load_module_with_sibling_imports(\n        \'basketball_master_sdv_predict\',\n        SDV_PREDICT_SCRIPT,\n    )\n    sdv_cfg = sdv_module.feature_generation.read_yaml(SDV_MODEL_CONFIG)\n    sdv_module.feature_generation.validate_config(sdv_cfg)\n\n    artifacts = sdv_module.load_artifacts(sdv_cfg, league.lower())\n    model_version, feature_version = sdv_module.validate_artifacts(\n        sdv_cfg,\n        league.lower(),\n        artifacts,\n    )\n    feature_map = _historical_feature_map(\n        base_df,\n        league,\n        internal_season,\n        sdv_module,\n        sdv_cfg,\n    )\n\n    predictions: dict[str, dict[str, Any]] = {}\n    for _, row in base_df.iterrows():\n        game_id = str(row[\'game_id\']).strip()\n        prediction = sdv_module.build_prediction_row(\n            slate_row=row.to_dict(),\n            feature_row=feature_map[game_id],\n            artifacts=artifacts,\n            model_version=model_version,\n            feature_version=feature_version,\n            prediction_generated_at=\'historical_master_validation\',\n        )\n        prediction[\'game_id\'] = game_id\n        predictions[game_id] = prediction\n\n    return predictions\n\n\ndef _raw_dratings_rows_for_ensemble(\n    base_df: pd.DataFrame,\n    league: str,\n    settings: dict[str, Any],\n    internal_season: int,\n) -> dict[str, dict[str, Any]]:\n    out: dict[str, dict[str, Any]] = {}\n    for _, row in base_df.iterrows():\n        game_id = str(row[\'game_id\']).strip()\n        raw_home, raw_away, raw_total = reverse_bias_row_to_raw(\n            row,\n            league,\n            settings,\n            internal_season,\n        )\n        payload = row.to_dict()\n        payload[\'game_id\'] = game_id\n        payload[\'home_projected_points\'] = raw_home\n        payload[\'away_projected_points\'] = raw_away\n        payload[\'total_projected_points\'] = raw_total\n        payload[\'bias_applied\'] = 0\n        out[game_id] = payload\n    return out\n\n\ndef apply_historical_model_source(\n    df: pd.DataFrame,\n    league: str,\n    settings: dict[str, Any],\n    model_source: str,\n    internal_season: int,\n) -> pd.DataFrame:\n    out = df.copy()\n\n    seen_sources: set[str] = set()\n    if \'model_source\' in out.columns:\n        seen_sources = {\n            str(v).strip().lower()\n            for v in out[\'model_source\'].dropna().tolist()\n            if str(v).strip()\n        }\n        if seen_sources and seen_sources != {model_source}:\n            raise ValueError(\n                f\'Input model_source values {sorted(seen_sources)} do not match \'\n                f\'requested model_source={model_source}\'\n            )\n\n    # An explicitly source-tagged historical file is already source-ready.\n    if seen_sources == {model_source}:\n        return out\n\n    if model_source == \'dratings\':\n        out[\'model_source\'] = \'dratings\'\n        return out\n\n    sdv_predictions = _historical_sdv_predictions(\n        out,\n        league,\n        internal_season,\n    )\n\n    if model_source == \'sdv\':\n        source_predictions = sdv_predictions\n    else:\n        ensemble_module = _load_module_with_sibling_imports(\n            \'basketball_master_ensemble\',\n            ENSEMBLE_SCRIPT,\n        )\n        weights = ensemble_module.load_weights(league.lower())\n        dratings_rows = _raw_dratings_rows_for_ensemble(\n            out,\n            league,\n            settings,\n            internal_season,\n        )\n        source_predictions: dict[str, dict[str, Any]] = {}\n        for game_id in out[\'game_id\'].astype(str).str.strip().tolist():\n            source_predictions[game_id] = ensemble_module.combine_game(\n                league=league.lower(),\n                game_id=game_id,\n                dratings=dratings_rows[game_id],\n                sdv=sdv_predictions[game_id],\n                weights=weights,\n                prediction_time=\'historical_master_validation\',\n            )\n\n    forecast_columns = (\n        \'home_prob\',\n        \'away_prob\',\n        \'home_projected_points\',\n        \'away_projected_points\',\n        \'total_projected_points\',\n    )\n    provenance_columns = (\n        \'model_version\',\n        \'feature_version\',\n        \'ensemble_version\',\n        \'sdv_model_version\',\n        \'sdv_feature_version\',\n    )\n\n    for index, row in out.iterrows():\n        game_id = str(row[\'game_id\']).strip()\n        prediction = source_predictions.get(game_id)\n        if prediction is None:\n            raise RuntimeError(\n                f\'{model_source}: missing historical prediction for game_id={game_id}\'\n            )\n        for column in forecast_columns:\n            if column not in prediction:\n                raise RuntimeError(\n                    f\'{model_source}: game_id={game_id} missing {column}\'\n                )\n            out.at[index, column] = prediction[column]\n        for column in provenance_columns:\n            if column in prediction:\n                out.at[index, column] = prediction[column]\n\n    out[\'model_source\'] = model_source\n    # SDV/ensemble projections are raw inputs to the production bias layer.\n    out[\'bias_applied\'] = 0\n    if \'margin_bias\' in out.columns:\n        out[\'margin_bias\'] = np.nan\n    if \'total_bias\' in out.columns:\n        out[\'total_bias\'] = np.nan\n\n    return out\n\n\ndef _bias_history_requirement(rule: dict[str, Any]) -> int:\n    normalized = normalize_production_bias_rule(rule)\n    method = normalized[\'method\']\n    if method in {\'none\', \'fixed\'}:\n        return 0\n    if method == \'rolling\':\n        return int(normalized[\'window_games\'])\n    return max(int(v) for v in normalized[\'windows_games\'])\n\n\ndef _production_fold_probabilities(\n    train: pd.DataFrame,\n    test: pd.DataFrame,\n    market: str,\n    settings: dict[str, Any],\n) -> tuple[np.ndarray, np.ndarray] | None:\n    if market == \'moneyline\':\n        return current_pipeline_probabilities(\n            test,\n            market,\n            settings,\n            prior_history=train,\n        )\n\n    rule = (\n        settings[\'MARGIN_BIAS_RULE\']\n        if market == \'spread\'\n        else settings[\'TOTAL_BIAS_RULE\']\n    )\n    if len(train) < _bias_history_requirement(rule):\n        return None\n\n    return current_pipeline_probabilities(\n        test,\n        market,\n        settings,\n        prior_history=train,\n    )\n\n\ndef _decimal_to_american(value: Any) -> float:\n    try:\n        decimal = float(value)\n    except Exception:\n        return np.nan\n    if not np.isfinite(decimal) or decimal <= 1.0:\n        return np.nan\n    if decimal >= 2.0:\n        return 100.0 * (decimal - 1.0)\n    return -100.0 / (decimal - 1.0)\n\n\ndef _flatten_selected_side_bets(\n    meta: pd.DataFrame,\n    selected: pd.DataFrame,\n    market: str,\n    model_source: str,\n) -> pd.DataFrame:\n    rows: list[dict[str, Any]] = []\n    side1, side2 = market_sides(market)\n\n    for position in range(len(selected)):\n        src = selected.iloc[position]\n        base = meta.iloc[position]\n        for side_index, side in ((1, side1), (2, side2)):\n            if not bool(src[f\'side{side_index}_selected\']):\n                continue\n            line = np.nan\n            if market == \'spread\':\n                line = float(\n                    base[\'home_spread\'] if side_index == 1 else base[\'away_spread\']\n                )\n            elif market == \'total\':\n                line = float(base[\'total\'])\n\n            decimal_odds = float(src[f\'side{side_index}_odds\'])\n            rows.append({\n                \'model_source\': model_source,\n                \'market\': market,\n                \'side\': side,\n                \'game_id\': str(src[\'game_id\']),\n                \'date\': src[\'date\'],\n                \'fold_id\': int(src[\'fold_id\']),\n                \'line\': line,\n                \'odds\': _decimal_to_american(decimal_odds),\n                \'decimal_odds\': decimal_odds,\n                \'ev\': float(src[f\'side{side_index}_ev\']),\n                \'kelly\': float(src[f\'side{side_index}_kelly\']),\n                \'model_prob\': float(src[f\'side{side_index}_prob\']),\n                \'edge_vs_market\': float(src[f\'side{side_index}_edge_vs_market\']),\n                \'result\': float(src[f\'side{side_index}_result\']),\n                \'profit\': float(src[f\'side{side_index}_profit\']),\n            })\n\n    return pd.DataFrame(rows)\n\n\ndef _development_oos_bets(\n    dev: pd.DataFrame,\n    settings: dict[str, Any],\n    selection_policies: dict[str, MarketSelectionPolicy],\n    model_source: str,\n) -> pd.DataFrame:\n    folds = make_outer_folds(dev, TARGET_OUTER_FOLDS)\n    frames: list[pd.DataFrame] = []\n\n    for fold_id, train_idx, test_idx in folds:\n        train = dev.iloc[train_idx]\n        test = dev.iloc[test_idx].copy()\n        test[\'fold_id\'] = fold_id\n        for market in (\'moneyline\', \'spread\', \'total\'):\n            probs = _production_fold_probabilities(\n                train,\n                test,\n                market,\n                settings,\n            )\n            if probs is None:\n                continue\n            p1, p2 = probs\n            base = market_opportunities(test, market, p1, p2)\n            selected = select_opportunities(\n                base,\n                selection_policies[market],\n                edge_mode=\'shared\',\n                shared_edge=current_edge_for_market(market, settings),\n            )\n            flat = _flatten_selected_side_bets(\n                test,\n                selected,\n                market,\n                model_source,\n            )\n            if not flat.empty:\n                frames.append(flat)\n\n    if not frames:\n        return pd.DataFrame()\n    return pd.concat(frames, ignore_index=True)\n\n\ndef _lockbox_bets(\n    dev: pd.DataFrame,\n    lockbox: pd.DataFrame,\n    settings: dict[str, Any],\n    selection_policies: dict[str, MarketSelectionPolicy],\n    model_source: str,\n) -> pd.DataFrame:\n    frames: list[pd.DataFrame] = []\n    for market in (\'moneyline\', \'spread\', \'total\'):\n        p1, p2 = current_pipeline_probabilities(\n            lockbox,\n            market,\n            settings,\n            prior_history=dev,\n        )\n        meta = lockbox.copy()\n        meta[\'fold_id\'] = 999\n        base = market_opportunities(meta, market, p1, p2)\n        selected = select_opportunities(\n            base,\n            selection_policies[market],\n            edge_mode=\'shared\',\n            shared_edge=current_edge_for_market(market, settings),\n        )\n        flat = _flatten_selected_side_bets(\n            meta,\n            selected,\n            market,\n            model_source,\n        )\n        if not flat.empty:\n            frames.append(flat)\n    if not frames:\n        return pd.DataFrame()\n    return pd.concat(frames, ignore_index=True)\n\n\ndef _bet_metrics(df: pd.DataFrame) -> dict[str, Any]:\n    if df.empty:\n        return {\n            \'bets\': 0,\n            \'profit_units\': 0.0,\n            \'roi\': np.nan,\n            \'positive_fold_rate\': np.nan,\n            \'folds\': 0,\n        }\n    profit = float(pd.to_numeric(df[\'profit\'], errors=\'coerce\').sum())\n    bets = int(len(df))\n    fold_profit = df.groupby(\'fold_id\')[\'profit\'].sum()\n    return {\n        \'bets\': bets,\n        \'profit_units\': profit,\n        \'roi\': profit / bets if bets else np.nan,\n        \'positive_fold_rate\': float((fold_profit > 0).mean()) if len(fold_profit) else np.nan,\n        \'folds\': int(len(fold_profit)),\n    }\n\n\ndef _snap_band_value(metric: str, value: float) -> float:\n    if metric == \'odds\':\n        return float(round(value / 25.0) * 25.0)\n    if metric == \'line\':\n        return float(round(value * 2.0) / 2.0)\n    if metric in {\'ev\', \'kelly\'}:\n        return float(round(value, 2))\n    if metric == \'model_prob\':\n        return float(round(value / 0.025) * 0.025)\n    if metric == \'edge_vs_market\':\n        return float(round(value))\n    return float(value)\n\n\ndef _candidate_intervals(df: pd.DataFrame, metric: str) -> list[tuple[float, float]]:\n    values = pd.to_numeric(df[metric], errors=\'coerce\').dropna()\n    if len(values) < 12:\n        return []\n    quantiles = np.unique(\n        np.quantile(\n            values.to_numpy(float),\n            [0.00, 0.05, 0.10, 0.15, 0.20, 0.25, 0.33,\n             0.50, 0.67, 0.75, 0.80, 0.85, 0.90, 0.95, 1.00],\n        )\n    )\n    cuts = sorted({_snap_band_value(metric, float(v)) for v in quantiles})\n    if len(cuts) < 2:\n        return []\n\n    intervals: set[tuple[float, float]] = set()\n    full_lo, full_hi = cuts[0], cuts[-1]\n    for cut in cuts[1:-1]:\n        intervals.add((cut, full_hi))\n        intervals.add((full_lo, cut))\n    for i in range(len(cuts) - 1):\n        for j in range(i + 1, len(cuts)):\n            lo, hi = cuts[i], cuts[j]\n            if lo < hi:\n                intervals.add((lo, hi))\n    intervals.discard((full_lo, full_hi))\n    return sorted(intervals)\n\n\ndef _apply_band_filters(\n    df: pd.DataFrame,\n    bands: dict[str, tuple[float, float]],\n) -> pd.DataFrame:\n    mask = np.ones(len(df), dtype=bool)\n    for metric, (lo, hi) in bands.items():\n        values = pd.to_numeric(df[metric], errors=\'coerce\').to_numpy(float)\n        mask &= np.isfinite(values) & (values >= lo) & (values <= hi)\n    return df.loc[mask].copy()\n\n\ndef _discover_side_bands(side_df: pd.DataFrame) -> dict[str, Any]:\n    baseline = _bet_metrics(side_df)\n    bands: dict[str, tuple[float, float]] = {}\n    if baseline[\'bets\'] < 12:\n        return {\n            \'bands\': bands,\n            \'baseline\': baseline,\n            \'development\': baseline,\n            \'status\': \'INSUFFICIENT_DEVELOPMENT_BETS\',\n        }\n\n    dimensions = [\'odds\', \'ev\', \'kelly\', \'model_prob\', \'edge_vs_market\']\n    if side_df[\'market\'].iloc[0] in {\'spread\', \'total\'}:\n        dimensions.insert(1, \'line\')\n\n    current = side_df.copy()\n    current_metrics = baseline\n    used: set[str] = set()\n\n    for _ in range(2):\n        best: tuple[Any, ...] | None = None\n        for metric in dimensions:\n            if metric in used:\n                continue\n            for lo, hi in _candidate_intervals(current, metric):\n                candidate_bands = dict(bands)\n                candidate_bands[metric] = (lo, hi)\n                candidate = _apply_band_filters(side_df, candidate_bands)\n                metrics = _bet_metrics(candidate)\n                min_bets = max(12, int(math.ceil(0.35 * baseline[\'bets\'])))\n                if metrics[\'bets\'] < min_bets:\n                    continue\n                if metrics[\'folds\'] < min(3, max(1, baseline[\'folds\'])):\n                    continue\n                current_roi = current_metrics[\'roi\']\n                roi_improvement = (\n                    metrics[\'roi\'] - current_roi\n                    if np.isfinite(metrics[\'roi\']) and np.isfinite(current_roi)\n                    else -np.inf\n                )\n                profit_improvement = (\n                    metrics[\'profit_units\'] - current_metrics[\'profit_units\']\n                )\n                stable = (\n                    not np.isfinite(metrics[\'positive_fold_rate\'])\n                    or metrics[\'positive_fold_rate\'] >= 0.50\n                )\n                if (\n                    profit_improvement < 0.50\n                    or roi_improvement < 0.01\n                    or not stable\n                ):\n                    continue\n                key = (\n                    profit_improvement,\n                    metrics[\'positive_fold_rate\']\n                    if np.isfinite(metrics[\'positive_fold_rate\']) else -1.0,\n                    roi_improvement,\n                    metrics[\'bets\'],\n                )\n                if best is None or key > best[0]:\n                    best = (key, metric, lo, hi, candidate, metrics)\n\n        if best is None:\n            break\n\n        _, metric, lo, hi, current, current_metrics = best\n        bands[metric] = (float(lo), float(hi))\n        used.add(metric)\n\n    status = \'CANDIDATE_FOUND\' if bands else \'NO_CHANGE_CANDIDATE\'\n    return {\n        \'bands\': bands,\n        \'baseline\': baseline,\n        \'development\': current_metrics,\n        \'status\': status,\n    }\n\n\ndef _format_bands(bands: dict[str, tuple[float, float]]) -> str:\n    if not bands:\n        return \'NO_CHANGE\'\n    return \'; \'.join(\n        f\'{metric}=[{lo:g},{hi:g}]\'\n        for metric, (lo, hi) in bands.items()\n    )\n\n\ndef _market_band_report_text(\n    input_file: Path,\n    markets_file: Path,\n    split_summary: pd.DataFrame,\n    candidates: pd.DataFrame,\n    comparison: pd.DataFrame,\n    markets_sha256: str,\n) -> str:\n    line = \'=\' * 100\n    carried = comparison[\n        (comparison[\'model_source\'] == \'ensemble\')\n        & (comparison[\'lockbox_status\'] == \'VALIDATED\')\n    ].copy()\n\n    parts = [\n        \'WNBA MARKET BANDS REPORT\',\n        line,\n        f\'Input: {input_file}\',\n        f\'Markets config (read only): {markets_file}\',\n        f\'markets.yaml sha256: {markets_sha256}\',\n        \'markets.yaml modified: NO\',\n        \'Band discovery source: ENSEMBLE only\',\n        \'DRatings and SDV are comparison-only; they do not choose band edges.\',\n        \'Candidate selection uses development/OOS rows only.\',\n        \'The lockbox is evaluated once after all candidate bands are frozen.\',\n        \'\',\n        \'SPLIT / SOURCE COVERAGE\',\n        line,\n        split_summary.to_string(index=False),\n        \'\',\n        \'DEVELOPMENT/OOS CANDIDATES (ENSEMBLE)\',\n        line,\n        candidates.to_string(index=False),\n        \'\',\n        \'UNTOUCHED LOCKBOX: DRATINGS vs SDV vs ENSEMBLE\',\n        line,\n        comparison.to_string(index=False),\n        \'\',\n        \'CARRY FORWARD TO ITEM 21\',\n        line,\n    ]\n\n    if carried.empty:\n        parts.append(\'No WNBA market-band changes validated on the untouched lockbox.\')\n    else:\n        for _, row in carried.iterrows():\n            parts.append(\n                f"{row[\'market\']} {row[\'side\']}: {row[\'candidate_bands\']}"\n            )\n\n    parts.extend([\n        \'\',\n        \'Do not modify markets.yaml during this item.\',\n        \'\',\n    ])\n    return \'\\n\'.join(parts)\n\n\ndef run_wnba_market_band_validation(\n    input_file: Path,\n    internal_season: int,\n    settings: dict[str, Any],\n    selection_policies: dict[str, MarketSelectionPolicy],\n    markets_file: Path,\n    output_path: Path,\n) -> Path:\n    if internal_season != 2025:\n        raise ValueError(\n            \'WNBA market-band validation currently requires the completed \'\n            \'2025_WNBA historical base file.\'\n        )\n\n    before_hash = hashlib.sha256(markets_file.read_bytes()).hexdigest()\n\n    source_frames: dict[str, pd.DataFrame] = {}\n    source_dev: dict[str, pd.DataFrame] = {}\n    source_lockbox: dict[str, pd.DataFrame] = {}\n    split_rows: list[dict[str, Any]] = []\n\n    expected_dev_ids: list[str] | None = None\n    expected_lock_ids: list[str] | None = None\n\n    for source in MODEL_SOURCES:\n        frame = load_data(\n            input_file,\n            \'WNBA\',\n            settings,\n            source,\n            internal_season,\n        )\n        dev, lockbox = split_development_lockbox(frame, LOCKBOX_FRACTION)\n        dev_ids = dev[\'game_id\'].astype(str).tolist()\n        lock_ids = lockbox[\'game_id\'].astype(str).tolist()\n        if expected_dev_ids is None:\n            expected_dev_ids = dev_ids\n            expected_lock_ids = lock_ids\n        elif dev_ids != expected_dev_ids or lock_ids != expected_lock_ids:\n            raise RuntimeError(\n                f\'{source}: WNBA development/lockbox game_id split differs \'\n                \'from the other model sources.\'\n            )\n        source_frames[source] = frame\n        source_dev[source] = dev\n        source_lockbox[source] = lockbox\n        split_rows.append({\n            \'model_source\': source,\n            \'full_games\': len(frame),\n            \'development_games\': len(dev),\n            \'lockbox_games\': len(lockbox),\n            \'development_start\': str(dev[\'_date\'].min().date()),\n            \'development_end\': str(dev[\'_date\'].max().date()),\n            \'lockbox_start\': str(lockbox[\'_date\'].min().date()),\n            \'lockbox_end\': str(lockbox[\'_date\'].max().date()),\n        })\n\n    dev_bets = _development_oos_bets(\n        source_dev[\'ensemble\'],\n        settings,\n        selection_policies,\n        \'ensemble\',\n    )\n    if dev_bets.empty:\n        raise RuntimeError(\'Ensemble WNBA development/OOS produced zero qualifying bets.\')\n\n    candidate_records: list[dict[str, Any]] = []\n    frozen_bands: dict[tuple[str, str], dict[str, tuple[float, float]]] = {}\n\n    for market in (\'moneyline\', \'spread\', \'total\'):\n        for side in market_sides(market):\n            subset = dev_bets[\n                (dev_bets[\'market\'] == market)\n                & (dev_bets[\'side\'] == side)\n            ].copy()\n            discovered = _discover_side_bands(subset)\n            bands = discovered[\'bands\']\n            frozen_bands[(market, side)] = bands\n            baseline = discovered[\'baseline\']\n            candidate = discovered[\'development\']\n            candidate_records.append({\n                \'market\': market,\n                \'side\': side,\n                \'status\': discovered[\'status\'],\n                \'candidate_bands\': _format_bands(bands),\n                \'dev_baseline_bets\': baseline[\'bets\'],\n                \'dev_baseline_profit\': baseline[\'profit_units\'],\n                \'dev_baseline_roi\': baseline[\'roi\'],\n                \'dev_candidate_bets\': candidate[\'bets\'],\n                \'dev_candidate_profit\': candidate[\'profit_units\'],\n                \'dev_candidate_roi\': candidate[\'roi\'],\n                \'dev_candidate_positive_fold_rate\': candidate[\'positive_fold_rate\'],\n            })\n\n    candidates = pd.DataFrame(candidate_records)\n\n    comparison_records: list[dict[str, Any]] = []\n    for source in MODEL_SOURCES:\n        lock_bets = _lockbox_bets(\n            source_dev[source],\n            source_lockbox[source],\n            settings,\n            selection_policies,\n            source,\n        )\n        for market in (\'moneyline\', \'spread\', \'total\'):\n            for side in market_sides(market):\n                baseline_df = lock_bets[\n                    (lock_bets[\'market\'] == market)\n                    & (lock_bets[\'side\'] == side)\n                ].copy()\n                bands = frozen_bands[(market, side)]\n                candidate_df = _apply_band_filters(baseline_df, bands)\n                baseline = _bet_metrics(baseline_df)\n                candidate = _bet_metrics(candidate_df)\n\n                if not bands:\n                    status = \'NO_CHANGE\'\n                elif candidate[\'bets\'] < 5:\n                    status = \'INSUFFICIENT_LOCKBOX_BETS\'\n                elif (\n                    candidate[\'profit_units\'] > 0\n                    and candidate[\'profit_units\'] >= baseline[\'profit_units\']\n                    and np.isfinite(candidate[\'roi\'])\n                    and candidate[\'roi\'] > 0\n                ):\n                    status = \'VALIDATED\'\n                else:\n                    status = \'REJECTED\'\n\n                comparison_records.append({\n                    \'model_source\': source,\n                    \'market\': market,\n                    \'side\': side,\n                    \'candidate_bands\': _format_bands(bands),\n                    \'lockbox_status\': status,\n                    \'baseline_bets\': baseline[\'bets\'],\n                    \'baseline_profit\': baseline[\'profit_units\'],\n                    \'baseline_roi\': baseline[\'roi\'],\n                    \'candidate_bets\': candidate[\'bets\'],\n                    \'candidate_profit\': candidate[\'profit_units\'],\n                    \'candidate_roi\': candidate[\'roi\'],\n                })\n\n    comparison = pd.DataFrame(comparison_records)\n    split_summary = pd.DataFrame(split_rows)\n\n    after_hash = hashlib.sha256(markets_file.read_bytes()).hexdigest()\n    if after_hash != before_hash:\n        raise RuntimeError(\n            f\'Refusing result: markets.yaml changed during validation: {markets_file}\'\n        )\n\n    output_path.parent.mkdir(parents=True, exist_ok=True)\n    output_path.write_text(\n        _market_band_report_text(\n            input_file,\n            markets_file,\n            split_summary,\n            candidates,\n            comparison,\n            before_hash,\n        ),\n        encoding=\'utf-8\',\n    )\n    return output_path\n'
SOURCE_OLD = "    if 'model_source' in df.columns:\n        seen_sources = {\n            str(v).strip().lower()\n            for v\n            in df[\n                'model_source'\n            ].dropna().tolist()\n            if str(v).strip()\n        }\n\n        if (\n            seen_sources\n            and seen_sources\n            != {\n                model_source\n            }\n        ):\n            raise ValueError(\n                'Input model_source values '\n                f'{sorted(seen_sources)} '\n                'do not match requested '\n                f'model_source={model_source}'\n            )\n\n    df[\n        'model_source'\n    ] = model_source\n"
SOURCE_NEW = '    df = apply_historical_model_source(\n        df,\n        league,\n        settings,\n        model_source,\n        internal_season,\n    )\n'
PARSER_ANCHOR = "    parser.add_argument(\n        '--quick',\n        action='store_true',\n        help=(\n            'Same logic, fewer bootstrap '\n            'scenarios for code validation'\n        ),\n    )\n"
PARSER_NEW = "    parser.add_argument(\n        '--quick',\n        action='store_true',\n        help=(\n            'Same logic, fewer bootstrap '\n            'scenarios for code validation'\n        ),\n    )\n\n    parser.add_argument(\n        '--wnba-market-bands',\n        action='store_true',\n        help=(\n            'Run Step 18 WNBA market-band validation: '\n            'ensemble development/OOS discovery, then one '\n            'untouched-lockbox comparison of dratings/sdv/ensemble.'\n        ),\n    )\n\n    parser.add_argument(\n        '--market-bands-output',\n        default=str(\n            WNBA_MARKET_BANDS_REPORT\n        ),\n        help=(\n            'Output path for the frozen WNBA market-band report.'\n        ),\n    )\n"
SEASON_ANCHOR = '    season = str(\n        internal_season\n    )\n'
SEASON_NEW = "    season = str(\n        internal_season\n    )\n\n    if args.wnba_market_bands:\n        if league != 'WNBA':\n            raise ValueError(\n                '--wnba-market-bands requires --league WNBA'\n            )\n\n        report_path = run_wnba_market_band_validation(\n            input_file=input_file,\n            internal_season=internal_season,\n            settings=settings,\n            selection_policies=selection_policies,\n            markets_file=markets_file,\n            output_path=Path(\n                args.market_bands_output\n            ),\n        )\n\n        progress(\n            'WNBA market-band validation complete: '\n            f'{report_path}'\n        )\n\n        return\n"
MAIN_MARKER = '\ndef main() -> None:\n'
MARKER = "# Step 18 additions for basketball_pipeline_final_master_test_core.py"

def require_once(text: str, needle: str, label: str) -> None:
    count = text.count(needle)
    if count != 1:
        raise RuntimeError(f"{label} expected exactly once; found {count}")


def main() -> int:
    if not CORE.exists():
        raise FileNotFoundError(CORE)
    if not LAUNCHER.exists():
        raise FileNotFoundError(LAUNCHER)

    launcher = LAUNCHER.read_text(encoding="utf-8")
    for required in (
        "'dratings'",
        "'sdv'",
        "'ensemble'",
        "'--model-source'",
        "production_prediction_source",
    ):
        if required not in launcher:
            raise RuntimeError(
                f"Launcher is not Step-18-ready; missing {required!r} in {LAUNCHER}"
            )

    text = CORE.read_text(encoding="utf-8")

    if MARKER in text:
        print(f"Step 18 already applied: {CORE}")
        return 0

    require_once(text, SOURCE_OLD, "model-source relabel block")
    require_once(text, PARSER_ANCHOR, "--quick parser block")
    require_once(text, SEASON_ANCHOR, "season assignment block")
    require_once(text, MAIN_MARKER, "main() marker")

    updated = text.replace(SOURCE_OLD, SOURCE_NEW, 1)
    updated = updated.replace(
        MAIN_MARKER,
        "\n\n" + ADDITIONS.rstrip() + "\n\n\ndef main() -> None:\n",
        1,
    )
    updated = updated.replace(PARSER_ANCHOR, PARSER_NEW, 1)
    updated = updated.replace(SEASON_ANCHOR, SEASON_NEW, 1)

    # Syntax validation occurs before the file is replaced.
    compile(updated, str(CORE), "exec")

    tmp = CORE.with_suffix(CORE.suffix + ".step18.tmp")
    tmp.write_text(updated, encoding="utf-8")
    tmp.replace(CORE)

    print(f"Updated: {CORE}")
    print(f"Launcher verified (no change required): {LAUNCHER}")
    print("markets.yaml modified: NO")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
